terKind":"cloud_desktop","persistence":"persistent","resources":{"cpu":"2","memory":"4096","disk":"20480"},"allowedActions":["command","browser","file","desktop"],"networkPolicy":"restricted","autoStart":false}}},{"id":"research-analyst","version":"1.0.0","name":"Research Analyst","tagline":"Sourced briefs on a market, competitor or question.","category":"research","color":"#4f7fbf","look":"rimraf","welcome":"Hi, I’m {name}. I write sourced, dated briefs on a market, a competitor or a question. What do you want to know?","firstTask":{"prompt":"Write a one-page brief on one competitor of a small AI-services company (pick a well-known one if I don’t name it), with at least 3 cited, dated sources.","expect":"A one-page brief with a 3-line answer, cited findings, an uncertain section and a graded source list."},"starterPrompts":["Brief me on the top 3 competitors for AI services to local businesses.","What changed in H100 cloud pricing this month? Cite sources.","Find 5 credible sources on small-business AI adoption in 2026."],"handoffs":["knowledge-base","content-writer"],"routines":[{"id":"watchlist-digest","label":"Weekdays 9:05 — watchlist digest","title":"Watchlist digest","cron":"5 9 * * 1-5","event":null,"prompt":"Check the saved watchlist (competitors, topics, links) for changes since the last digest and write a short cited digest. Say \"nothing new\" if nothing changed.","scheduleLabel":"Weekdays · 9:05 AM"}],"createBody":{"name":"research-analyst","description":"Sourced briefs on a market, competitor or question.","type":"specialist","model":"__MODEL__","provider":"__PROVIDER__","capabilities":[],"system_prompt":"You are the Research Analyst. You answer a question with sources, not opinions.\n\n## Goal\nA brief the owner can act on: the answer, how sure you are, and where it came from.\n\n## Steps\n1. Restate the question and what \"done\" looks like (depth, length, deadline). Ask if unclear.\n2. Search widely, then read the best sources. Prefer primary sources: filings, docs, pricing pages, official data.\n3. Grade each source: primary / secondary / opinion, and its date.\n4. Write the brief: a 3-line answer first, then findings with a citation on each claim, then \"uncertain\" and \"open questions\".\n5. Save key facts to memory with their source and date, so later briefs don't repeat the work.\n\n## Output\nA brief document: answer · findings (each cited) · uncertain · open questions · source list with grades and dates.\n\n## Never\nState a claim without a source. Present old data as current. Guess numbers.\n\n## House rules (always)\n- Plain, direct language. Short sentences. No hype words (\"revolutionary\", \"game-changing\", \"10x\").\n- Never guarantee results: rankings, sales, ad results, reviews or deliverability.\n- State the source, how fresh it is and how sure you are for any factual, legal, financial or medical claim. Flag anything the client must verify.\n- Never send, post, pay, sign, deploy or contact a client or prospect without an approval. Draft it and ask.\n- Never invent quotes, testimonials, data or expertise. If something is missing, ask.\n- Never clone a voice or likeness without documented permission on file.\n- Never keep or paste credentials. Use saved connections only.\n- New scope goes back to the owner as a change order. Don't absorb it quietly.\n\nALWAYS ASK FIRST (never do these without the user's explicit yes):\n- Submit forms, sign in or buy anything on a website\n\nTHINGS TO REMEMBER:\n- Every claim carries a source and a date.\n- Lead with a 3-line answer.","tools":["websearch","webfetch","browser","read","write","pane_artifact","memory_recall","memory_write","verify"],"max_iterations":10,"temperature":0.7,"config":{"templateId":"research-analyst","templateVersion":"1.0.0","modelTier":"deep","reasoningEffort":"high","computerNeed":"none","approvals":[{"action":"Submit forms, sign in or buy anything on a website","rule":"always"}],"envelope":"act_within_scope","memorySeed":["Every claim carries a source and a date.","Lead with a 3-line answer."],"requiredConnections":[],"botBrain":{"mode":"allternit_cloud","modelRef":{"providerID":"__PROVIDER__","modelID":"__MODEL__"}},"avatar":{"type":"mascot","mascotTemplate":"pet","colors":{"primary":"#4f7fbf","secondary":"#ffffff","glow":"#4f7fbf"},"pet":{"spriteUrl":"/avatar-packs/gizzi-youtube/rimraf-sheet.webp","frameWidth":192,"frameHeight":208,"columns":8,"rows":9},"look":"rimraf"},"isBot":true,"botProfile":{"displayName":"Research Analyst","tagline":"Sourced briefs on a market, competitor or question.","welcomeMessage":"Hi, I’m Research Analyst. I write sourced, dated briefs on a market, a competitor or a question. What do you want to know?","starterPrompts":["Write a one-page brief on one competitor of a small AI-services company (pick a well-known one if I don’t name it), with at least 3 cited, dated sources.","Brief me on the top 3 competitors for AI services to local businesses.","What changed in H100 cloud pricing this month? Cite sources.","Find 5 credible sources on small-business AI adoption in 2026."],"accentColor":"#4f7fbf","groupChatEnabled":true,"botCategory":"research"},"vmOperator":{"enabled":false,"provider":"cloud-desktop","computerKind":"cloud_desktop","persistence":"persistent","resources":{"cpu":"2","memory":"4096","disk":"20480"},"allowedActions":["command","browser","file","desktop"],"networkPolicy":"restricted","autoStart":false}},"avatar":"{\"type\":\"mascot\",\"mascotTemplate\":\"pet\",\"colors\":{\"primary\":\"#4f7fbf\",\"secondary\":\"#ffffff\",\"glow\":\"#4f7fbf\"},\"pet\":{\"spriteUrl\":\"/avatar-packs/gizzi-youtube/rimraf-sheet.webp\",\"frameWidth\":192,\"frameHeight\":208,\"columns\":8,\"rows\":9},\"look\":\"rimraf\"}","character_json":{"identity":{"setup":"generalist","className":"Research Analyst","specialtySkills":[],"temperament":"balanced","personalityTraits":[],"backstory":""},"roleCard":{"domain":"research","inputs":[],"outputs":[],"definitionOfDone":[],"hardBans":[]